import { test, expect } from '@playwright/test';

test.describe('Dropdown selection tests', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/dropdown');
  });

  test('should show disabled prompt initially', async ({ page }) => {
    const dropdown = page.getByLabel('Dropdown');
    await expect(dropdown).toHaveText('Please select an option');
  });

  test('should select Option 2 and update the value', async ({ page }) => {
    const dropdown = page.getByLabel('Dropdown');
    await dropdown.selectOption('2');
    await expect(dropdown).toHaveValue('2');
    await expect(dropdown).toHaveText('Option 2');
  });
});
